import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.1Y430-yj.js";const u=JSON.parse('{"title":"Planting and Automatic-Harvester Mechanics: Research and Applications","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"种植与自动收割机机制研究与应用","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=atfxNNyQUUJH68TDGeR9Vl","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-atfxNNyQUUJH68TDGeR9Vl.md","filePath":"logistics/src/page-atfxNNyQUUJH68TDGeR9Vl.md","lastUpdated":null}'),o={name:"logistics/src/page-atfxNNyQUUJH68TDGeR9Vl.md"};function r(n,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="种植与自动收割机机制研究与应用" aria-hidden="true"></span><h1 id="planting-and-automatic-harvester-mechanics-research-and-applications" tabindex="-1">Planting and Automatic-Harvester Mechanics: Research and Applications <a class="header-anchor" href="#planting-and-automatic-harvester-mechanics-research-and-applications" aria-label="Permalink to &quot;Planting and Automatic-Harvester Mechanics: Research and Applications&quot;">​</a></h1><blockquote><p>Source page ID: <code>atfxNNyQUUJH68TDGeR9Vl</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=atfxNNyQUUJH68TDGeR9Vl" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Page created by: ko鸟</p><p>Contributors: ko鸟, jnk (remember to add your name if you write something!)</p><p>Last updated: 2026-10-17</p><p>Note: the content may change with version updates.</p><p><span id="source-block-1EM2GjaCSjUNevMZLWaYrj"></span></p><span class="logistics-source-anchor" id="田地的机制" aria-hidden="true"></span><h2 id="plot-mechanics" tabindex="-1">Plot Mechanics <a class="header-anchor" href="#plot-mechanics" aria-label="Permalink to &quot;Plot Mechanics&quot;">​</a></h2><p><span id="source-block-iPYraacA0L1rll8TWggsvk"></span></p><span class="logistics-source-anchor" id="地块生长周期" aria-hidden="true"></span><h3 id="plot-growth-cycles" tabindex="-1">Plot Growth Cycles <a class="header-anchor" href="#plot-growth-cycles" aria-label="Permalink to &quot;Plot Growth Cycles&quot;">​</a></h3><p>A growth cycle consists of several stages. Some require interaction by the player or equipment (such as starting seedlings and watering); others require waiting for crops to grow.</p><p>Click a plot in the game to view its crop&#39;s growth cycle.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-5c392cde2dba0456.q90-74df595a6ca55216.webp" alt="Planting and Automatic-Harvester Mechanics: Research and Applications"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-e972e4587eb7c624.q90-bc132a54bddbcf22.webp" alt="Planting and Automatic-Harvester Mechanics: Research and Applications"></p><p>Crop growth-cycle list:</p><ul><li><p>Buckflower, Citrome:</p></li><li><p>Yazhen, Jincao</p></li><li><p>Reed Rye, Tartpepper</p></li><li><p>Amber Rice, Redjade Ginseng</p></li><li><p>Pingtuber, Ballpea, Matoberry, Crunchcane, Oilseed Bloom, Whitemelon</p></li><li><p>Relishroom, Cabbage, Sourberry</p></li></ul><p><span id="source-block-Wdc2VvTg4d9uvdJi2pwh7S"></span></p><span class="logistics-source-anchor" id="成熟时间与产出" aria-hidden="true"></span><h3 id="maturation-time-and-yield" tabindex="-1">Maturation Time and Yield <a class="header-anchor" href="#maturation-time-and-yield" aria-label="Permalink to &quot;Maturation Time and Yield&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Maturation time<br>Growth stages only</th><th>Requirements</th><th>Main output<br>Base yield</th><th>Secondary output<br>Base yield</th></tr></thead><tbody><tr><td>Buckflower, Citrome</td><td></td><td>Watering</td><td>10 crops</td><td>1-3 high-quality crops</td></tr><tr><td>Yazhen, Jincao</td><td>1 hour</td><td>Water 2 times</td><td>10 crops</td><td>1-3 high-quality crops</td></tr><tr><td>Reed Rye, Tartpepper</td><td>12 hours</td><td>Watering</td><td>30 crops</td><td></td></tr><tr><td>Amber Rice, Redjade Ginseng</td><td>12 hours</td><td>Water 3 times</td><td>30 crops</td><td></td></tr><tr><td>The crops above have no placement restrictions; plots for the crops below can only be placed in Si&#39;s Painting</td><td></td><td></td><td></td><td></td></tr><tr><td>Pingtuber, Ballpea</td><td>8 hours</td><td>Watering</td><td>30 crops</td><td></td></tr><tr><td>Matoberry, Crunchcane, Oilseed Bloom, Whitemelon</td><td>8 hours</td><td>Watering</td><td>30 crops</td><td></td></tr><tr><td>Relishroom, Cabbage, Sourberry (non-mutated)</td><td>8 hours</td><td>Watering</td><td>30 crops</td><td></td></tr><tr><td>Relishroom, Cabbage, Sourberry (mutated)</td><td>8 hours</td><td>Non-mutated version exposed to a Xiragen environment for 30s</td><td>30 crops</td><td>30 mutated crops</td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><span id="source-block-IV3hvhDZTnbS1fqEpawiIx"></span></p><span class="logistics-source-anchor" id="浇水方式以及消耗" aria-hidden="true"></span><h3 id="watering-methods-and-consumption" tabindex="-1">Watering Methods and Consumption <a class="header-anchor" href="#watering-methods-and-consumption" aria-label="Permalink to &quot;Watering Methods and Consumption&quot;">​</a></h3><p><span id="source-block-IIhvOBmohhOcx7qBPq5stH"></span></p><span class="logistics-source-anchor" id="浇水机" aria-hidden="true"></span><h4 id="sprinkler" tabindex="-1">Sprinkler <a class="header-anchor" href="#sprinkler" aria-label="Permalink to &quot;Sprinkler&quot;">​</a></h4><p>At present, every plot&#39;s watering stage requires a Sprinkler to supply 30 units of water. When one Sprinkler waters multiple plots, all plots advance at the same rate; adding more plots does not consume additional water.</p><p>Because the Sprinkler automatically starts watering when a plot within its range enters the watering stage, it can also detect plot states.</p><p><span id="source-block-ILlc7DlSxgouw8GOYWkRso"></span></p><span class="logistics-source-anchor" id="气体散布机" aria-hidden="true"></span><h4 id="gas-dispersing-unit" tabindex="-1">Gas Dispersing Unit <a class="header-anchor" href="#gas-dispersing-unit" aria-label="Permalink to &quot;Gas Dispersing Unit&quot;">​</a></h4><p>Aquagen can be fed into a Gas Dispersing Unit to create a humid environment. Plots within that environment automatically advance their watering progress while in the watering stage. Since the consumption required to maintain the humid environment is fixed, adding more plots clearly does not consume additional Aquagen.</p><p>With rate limiting set to 6, inputting 4 Aquagen completes a plot&#39;s watering stage. Tests found that 3 Aquagen leaves just the tiniest bit of progress unfinished, possibly because the disperser is not operating continuously.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-0e8510f12f21e4d6.q90-90df22ac67c30690.webp" alt="Planting and Automatic-Harvester Mechanics: Research and Applications"></p><p><span id="source-block-EkwbvKCZKxA1Z86uAFjeqG"></span></p><span class="logistics-source-anchor" id="变异与相邻增产" aria-hidden="true"></span><h3 id="mutation-and-adjacency-yield-bonuses" tabindex="-1">Mutation and Adjacency Yield Bonuses <a class="header-anchor" href="#mutation-and-adjacency-yield-bonuses" aria-label="Permalink to &quot;Mutation and Adjacency Yield Bonuses&quot;">​</a></h3><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-14e1ddb91f3a6632.q90-a004668fedaa1af9.webp" alt="Planting and Automatic-Harvester Mechanics: Research and Applications"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-c6bfd46b6dcc69eb.q90-c56e1cc439e812a4.webp" alt="Planting and Automatic-Harvester Mechanics: Research and Applications"></p><p>After a watered, non-mutated plot is exposed to a Xiranite environment for 30s, which need not be continuous (no further exposure is needed before harvesting), it becomes a mutated plant plot while retaining its elapsed growth time. After mutation, it undergoes a 30s adjacency-yield-bonus process.</p><p>When plots of the same plant are adjacent, each neighboring plant plot adds 20% yield (additively), regardless of whether that neighboring plot has mutated.</p><p>The adjacency bonus is actually calculated at harvest, rather than during the adjacency-bonus process. In other words, changing the layout after those 30s changes the yield bonus.</p><p>Harvesting or reclaiming the plot returns it to its ordinary form.</p><p><span id="source-block-9wJKZMeO4XEBGfQwgjyxwS"></span></p><span class="logistics-source-anchor" id="肥料机制" aria-hidden="true"></span><h3 id="fertilizer-mechanics" tabindex="-1">Fertilizer Mechanics <a class="header-anchor" href="#fertilizer-mechanics" aria-label="Permalink to &quot;Fertilizer Mechanics&quot;">​</a></h3><p>Fertilizer yield bonuses add to adjacency yield bonuses.</p><p><span id="source-block-8PqQsBoHitKAo26fgJLofp"></span></p><span class="logistics-source-anchor" id="收割机基本规律" aria-hidden="true"></span><h2 id="basic-harvester-rules" tabindex="-1">Basic Harvester Rules <a class="header-anchor" href="#basic-harvester-rules" aria-label="Permalink to &quot;Basic Harvester Rules&quot;">​</a></h2><p><span id="source-block-CHWrkPO22DCEc4i1bEGG2s"></span></p><span class="logistics-source-anchor" id="收割时机" aria-hidden="true"></span><h3 id="when-harvesting-occurs" tabindex="-1">When Harvesting Occurs <a class="header-anchor" href="#when-harvesting-occurs" aria-label="Permalink to &quot;When Harvesting Occurs&quot;">​</a></h3><p>It can essentially be considered to check at all times for mature plots. If a plot is mature and the output fits into storage slots (even if only some of it fits; see below), it is harvested. Offline behavior is unknown.</p><p>If harvesting is possible, the outputs go into storage slots (overflow is automatically destroyed; see below), and the harvester automatically performs the seedling operation on the plot, which has returned to the seedling stage. Combined with Aquagen dispersal or a Sprinkler, this lets the plot enter its growth stage directly after watering finishes.</p><p><span id="source-block-d9eu8EqE2npBGUd2aqLVEq"></span></p><span class="logistics-source-anchor" id="收割顺序" aria-hidden="true"></span><h3 id="harvest-order" tabindex="-1">Harvest Order <a class="header-anchor" href="#harvest-order" aria-label="Permalink to &quot;Harvest Order&quot;">​</a></h3><p>Current evidence rules out harvesting by position, maturation time, and placement order.</p><p>We still have absolutely no idea what determines the order...</p><p><span id="source-block-XbsbxMYQVCSxxsYgX0L8lN"></span></p><span class="logistics-source-anchor" id="收割时产物溢出的判断" aria-hidden="true"></span><h3 id="how-output-overflow-is-handled-at-harvest" tabindex="-1">How Output Overflow Is Handled at Harvest <a class="header-anchor" href="#how-output-overflow-is-handled-at-harvest" aria-label="Permalink to &quot;How Output Overflow Is Handled at Harvest&quot;">​</a></h3><p><strong>For single-output crops, such as Whitemelon and Crunchcane</strong></p><p><span class="mark-purple"><u>a. If the harvester has a non-full slot for the crop, but no other slot can accept more of it, it steals and eats the amount exceeding that slot&#39;s limit of 50.</u></span></p><p>Example: one slot holds 30 Whitemelon; every other slot holds other crops or 50 Whitemelon. Harvest another Whitemelon plot: that slot becomes 50, and the extra 10 simply vanish.</p><p><strong>For non-mutated crops with secondary outputs, such as Pingtuber and beans</strong></p><p>Free space for either the main or secondary output triggers harvesting, and rule a still applies.</p><p><span class="mark-purple"><u>b. With only the last storage slot left, the main product is stored and the secondary product is stolen and eaten.</u></span></p><p>Example: with one slot left, harvest a potato plot. The 30 potatoes enter storage, while 3 potato leaves simply vanish. Harvest another plot: 20 enter storage, and 10 potatoes plus 3 leaves simply vanish.</p><p><span class="mark-purple"><u>c. When the secondary product is not full but the main product is full, the entire main output is stolen and eaten.</u></span></p><p>Example: with only two slots left, harvest a potato plot: 30 potatoes and 3 leaves enter storage. Harvest again: 20 potatoes and 3 leaves enter storage, while 10 potatoes disappear. If more potato plots remain, harvesting continues: 3 leaves enter storage and 50 potatoes simply disappear. This can steal up to 450 of your potatoes.</p><p><a href="https://www.bilibili.com/video/BV1PLJ86VEnr" target="_blank" rel="noreferrer">Endfield: In Case You Didn&#39;t Know Automatic Harvesters Steal Potatoes</a></p><blockquote><p>Seriously? It&#39;s 1.6, and there&#39;s another freeloading pig?</p></blockquote><p>Because potato leaves are produced in such small quantities, harvesting doesn&#39;t stop when potatoes are full but their leaves aren&#39;t. It just keeps harvesting potatoes, and all the potatoes that don&#39;t fit get eaten! I&#39;m furious!<br> Probably peas too.</p><p><strong>For mutated crops, such as mutated Cabbage</strong></p><p>A mutated plot simultaneously produces equal quantities of the mutated and non-mutated versions.</p><p>If the non-mutated version is treated as the main product and the mutated version as the secondary product (a little strange though that is), rules a-c still apply.</p><p>Note: because the non-mutated version is stored first, with only 1 slot left it can crowd out the mutated version.</p><hr><p><span id="source-block-BSLjmbYaB0yYBBzfnHhX7E"></span></p><span class="logistics-source-anchor" id="应用方案" aria-hidden="true"></span><h2 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;Applications&quot;">​</a></h2><p><span id="source-block-mGNGNOSKycEqigA1nGal5C"></span></p><span class="logistics-source-anchor" id="方案名" aria-hidden="true"></span><h3 id="scheme-name" tabindex="-1">Scheme Name <a class="header-anchor" href="#scheme-name" aria-label="Permalink to &quot;Scheme Name&quot;">​</a></h3><p>Problem addressed:</p><p>Layout:</p><p>君&#39;s idea: first detector plot is harvested → watering of first plot is detected → enable Aquagen watering for other plots → water second detector plot → second detector plot is harvested → watering of second plot is detected → enable Aquagen watering for other plots → water first detector plot.</p><p>The aim is for the detector plot to be harvested last.</p><p><span id="source-block-FrtI9vYcnh1hT51KUWajaY"></span></p><span class="logistics-source-anchor" id="方案名-1" aria-hidden="true"></span><h3 id="scheme-name-1" tabindex="-1">Scheme Name <a class="header-anchor" href="#scheme-name-1" aria-label="Permalink to &quot;Scheme Name&quot;">​</a></h3><p>Problem addressed:</p><p>Layout:</p><blockquote><p>Translation note: The source says “50 potatoes” disappear in the later rule-c example despite earlier describing a 30-potato harvest; both figures are retained. The automatic harvester is a specific in-game device confirmed by the user, but “automatic harvester” remains a provisional English name pending an exact localization match. Oilseed Bloom is the confirmed identity of the source’s “rapeseed” nickname; “potatoes” and “beans” retain the author’s informal wording.</p></blockquote></div>',1)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
